using Fleet.Api.Data; using Fleet.Api.Models; using Microsoft.EntityFrameworkCore;
namespace Fleet.Api.Services;
public sealed class AssignmentService(FleetDbContext db){public async Task<Assignment> AssignAsync(int vehicleId,int driverId,DateTime startsAt,string purpose,int creatorId,CancellationToken ct=default){if(startsAt<DateTime.UtcNow.AddMinutes(-5))throw new ArgumentException("Start time cannot be in the past.");if(string.IsNullOrWhiteSpace(purpose))throw new ArgumentException("Purpose is required.");await using var tx=await db.Database.BeginTransactionAsync(ct);var vehicle=await db.Vehicles.SingleOrDefaultAsync(x=>x.Id==vehicleId,ct)??throw new KeyNotFoundException("Vehicle not found.");var driver=await db.Drivers.SingleOrDefaultAsync(x=>x.Id==driverId,ct)??throw new KeyNotFoundException("Driver not found.");if(vehicle.Status!="Available")throw new InvalidOperationException("Vehicle is unavailable.");if(!driver.Active||driver.LicenseExpiresOn<DateOnly.FromDateTime(startsAt))throw new InvalidOperationException("Driver is inactive or license is expired.");if(await db.Assignments.AnyAsync(x=>x.EndsAt==null&&(x.VehicleId==vehicleId||x.DriverId==driverId),ct))throw new InvalidOperationException("Vehicle or driver already has an active assignment.");vehicle.Status="Assigned";var assignment=new Assignment{VehicleId=vehicleId,DriverId=driverId,StartsAt=startsAt.ToUniversalTime(),Purpose=purpose.Trim(),CreatedById=creatorId};db.Assignments.Add(assignment);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return assignment;}
public async Task<Assignment> CompleteAsync(int id,int odometer,CancellationToken ct=default){await using var tx=await db.Database.BeginTransactionAsync(ct);var item=await db.Assignments.Include(x=>x.Vehicle).SingleOrDefaultAsync(x=>x.Id==id,ct)??throw new KeyNotFoundException();if(item.EndsAt!=null)throw new InvalidOperationException("Assignment is already complete.");if(odometer<item.Vehicle!.Odometer)throw new ArgumentException("Odometer cannot decrease.");item.EndsAt=DateTime.UtcNow;item.Vehicle.Odometer=odometer;item.Vehicle.Status="Available";await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return item;}}
